bool APCCommManager::handleMarqueeSystemEvent(MqEvent mqEvent, const char *UNUSED(recvBuffer))
{
	UNREFERENCED_PARAMETER(recvBuffer);
	
	char str[255];
	DWORD result = OK;
	bool is_custom_code = false;

	switch (mqEvent)
	{
		/*messages sent out to usb device*/
		case MqSysReqStatus:		
		{
			Debug::trace("APCCommManager.MarqueeSystem.Message.Out", string("SysReqStatus:") + 
				Bool::toString(printerRequestedStatus_) + Bool::toString(numericRequestedStatus_) +
				Bool::toString(marqueeRequestedStatus_) + Bool::toString(weigherRequestedStatus_));	

			if (!printerRequestedStatus_ && !numericRequestedStatus_ && !weigherRequestedStatus_)//!marqueeRequestedStatus_
			{
				marqueeRequestedStatus_ = true;

				SysGenericMsg genMsg;
				memset((char *) &genMsg, 0, sizeof(genMsg));

				genMsg.function_code = SysStatus;

				usbEvolHdr_.setDestinationLogicalAddress(USBEvolHeader::SYSTEM);
				usbEvolHdr_.setMessageLength(sizeof(genMsg));
				usbEvolHdr_.Serialize( str );

				memcpy( &str[10], (char *) &genMsg, sizeof(genMsg));
				sendUsbInterruptMessage( ( const char * ) str,  sizeof(genMsg) + 10, result, is_custom_code );

			}
			else
				marqueeRequestedStatus_ = true;

		}
		break;

		default:
		{
			Debug::trace("APCCommManager.Error", HobString("Some Other Sytem Event: ") +
												 HobString(Integer::toString((UINT16) mqEvent)));
		}
		break;

	}

	if ( result != OK ) //error
	{
		printUSBError( result, is_custom_code );
	}

	return true;

}

